export default class SourceIcon extends React.Component {
  readonly props: {
    url?: string,
    type?: string,
    className?: string,
    sx?: any,
    style?: any,
  };

  render() {
    let type = "";
    if (this.props.url) {
      type = getSourceType(this.props.url);
    } else if (this.props.type) {
      type = this.props.type;
    }
    switch(type) {
      case ST.audio:
        return <AudiotrackIcon sx={this.props.sx} style={this.props.style} className={this.props.className} />
      case ST.local:
        return <FolderIcon sx={this.props.sx} style={this.props.style} className={this.props.className}/>;
      case ST.video:
        return <MovieIcon sx={this.props.sx} style={this.props.style} className={this.props.className}/>;
      case ST.playlist:
        return <SubscriptionsIcon sx={this.props.sx} style={this.props.style} className={this.props.className}/>;
      case ST.list:
        return <ListIcon sx={this.props.sx} style={this.props.style} className={this.props.className}/>;
      case ST.danbooru:
      case ST.e621:
        return <DanbooruIcon sx={this.props.sx} style={this.props.style} className={this.props.className}/>;
      case ST.booruScrape:
      case ST.booruAPI:
      case ST.gelbooru:
        return <GelbooruIcon sx={this.props.sx} style={this.props.style} className={this.props.className}/>;
      case ST.rule34:
        return <Rule34Icon sx={this.props.sx} style={this.props.style} className={this.props.className}/>;
      case ST.ehentai:
        return <EHentaiIcon sx={this.props.sx} style={this.props.style} className={this.props.className}/>;
      case ST.bdsmlr:
        return <BDSMlrIcon sx={this.props.sx} style={this.props.style} className={this.props.className}/>;
      case ST.hydrus:
        return <HydrusIcon sx={this.props.sx} style={this.props.style} className={this.props.className}/>;
      case ST.piwigo:
        return <PiwigoIcon sx={this.props.sx} style={this.props.style} className={this.props.className}/>;
      case ST.luscious:
        return <LusciousIcon sx={this.props.sx} style={this.props.style} className={this.props.className}/>;
      default:
        return <div/>
    }
  }
}

(SourceIcon as any).displayName="SourceIcon";
