export function changeThemeColor(state: State, colorTheme: any, primary: boolean): Object {
  if (primary) {
    state.theme.palette.primary = colorTheme;
    const type = state.theme.palette.mode;
    if (type === "dark") {
      (state.theme.palette as any).background = {};
    } else if (type === "light") {
      (state.theme.palette as any).background = {default: colorTheme[50]};
    }
  } else {
    state.theme.palette.secondary = colorTheme;
  }
  return {theme: state.theme};
}

